// Creates editable design layers and navigation for the BiteMatch example sessions.
/** @param {string | undefined} color @returns {SolidPaint[]} */
function solid(color) {
  const channels = color && color.match(/[\d.]+/g);
  if (!channels || channels[3] === '0') return [];
  const [r, g, b, alpha = 1] = channels.map(Number);
  return [{ type: 'SOLID', color: { r: r / 255, g: g / 255, b: b / 255 }, opacity: alpha }];
}

function position(node, parent, box) {
  const [x, y, width, height] = box;
  parent.appendChild(node);
  node.resize(Math.max(0.01, width), Math.max(0.01, height));
  node.x = x;
  node.y = y;
  return node;
}

async function getFonts() {
  const available = (await figma.listAvailableFontsAsync()).map(item => item.fontName);
  const family = available.some(font => font.family === 'Bricolage Grotesque' && font.style === 'Regular') ? 'Bricolage Grotesque' : 'Inter';
  const font = (...styles) => styles.map(style => available.find(candidate =>
    candidate.family === family && style.test(candidate.style))).find(Boolean);
  const regular = font(/^Regular$/i);
  if (!regular) throw new Error('A regular design font is unavailable.');
  const bold = font(/^Bold$/i) || regular;
  const heavy = font(/^Extra\s?Bold$/i, /^Black$/i) || bold;
  await Promise.all([regular, bold, heavy].map(name => figma.loadFontAsync(name)));
  return weight => weight >= 800 ? heavy : weight >= 650 ? bold : regular;
}

function draw(parent, layer, assets, font) {
  if (layer.kind === 'text') {
    const node = figma.createText();
    parent.appendChild(node);
    node.name = layer.name;
    node.fontName = font(layer.weight);
    node.fontSize = layer.size;
    node.fills = solid(layer.color);
    node.letterSpacing = { value: layer.track, unit: 'PIXELS' };
    node.characters = layer.text;
    node.x = layer.box[0];
    node.y = layer.box[1] + (layer.box[3] - node.height) / 2;
    return;
  }
  const node = position(figma.createRectangle(), parent, layer.box);
  node.name = layer.name.replace(/^[ \t]+|[ \t]+$/g, '') || 'Surface';
  node.cornerRadius = Math.min(layer.radius || 0, layer.box[2] / 2, layer.box[3] / 2);
  if (layer.kind === 'image') {
    node.fills = [{ type: 'IMAGE', imageHash: assets[layer.asset], scaleMode: layer.fit === 'cover' ? 'FILL' : 'FIT' }];
  } else {
    node.fills = solid(layer.fill);
    if (layer.border) {
      node.strokes = solid(layer.stroke);
      node.strokeWeight = layer.border;
      node.strokeAlign = 'INSIDE';
    }
  }
}

async function buildPrototype() {
  if (figma.editorType !== 'figma') throw new Error('Open the prototype in a Figma Design file.');
  const font = await getFonts();
  const assets = Object.fromEntries(Object.entries(prototypeData.images).map(([key, base64]) =>
    [key, figma.createImage(figma.base64Decode(base64)).hash]));
  const page = figma.createPage();
  page.name = 'BiteMatch · Clickable prototype';
  await figma.setCurrentPageAsync(page);
  const starts = [];
  /** @type {FrameNode | undefined} */
  let firstScreen;
  let y = 0;
  let count = 0;
  for (const { name, width, frames } of prototypeData.designs) {
    const nodes = new Map();
    const interactive = [];
    const columns = name === 'Mobile' ? 7 : 4;
    const gap = 90;
    const tallest = Math.max(...frames.map(frame => frame.contentHeight));
    for (const [index, spec] of frames.entries()) {
      const frame = figma.createFrame();
      frame.name = name + ' / ' + String(index + 1).padStart(2, '0') + ' ' + spec.title;
      frame.resize(width, spec.height);
      frame.x = (index % columns) * (width + gap);
      frame.y = y + Math.floor(index / columns) * (tallest + gap);
      frame.fills = solid('rgb(255, 246, 235)');
      frame.clipsContent = true;
      frame.overflowDirection = spec.contentHeight > spec.height ? 'VERTICAL' : 'NONE';
      const content = position(figma.createFrame(), frame, [0, 0, width, spec.contentHeight]);
      content.name = 'Screen content';
      content.fills = [];
      content.clipsContent = false;
      for (const layer of spec.layers) draw(content, layer, assets, font);
      for (const hotspot of spec.hotspots) {
        const target = position(figma.createRectangle(), content, hotspot.box);
        target.name = 'Interaction · ' + hotspot.name.replace(/\s+/g, ' ').slice(0, 58);
        target.fills = [{ type: 'SOLID', color: { r: 0, g: 0, b: 0 }, opacity: 0.001 }];
        interactive.push([target, hotspot]);
      }
      nodes.set(spec.id, frame);
      if (spec.id === 'start') {
        starts.push({ name, nodeId: frame.id });
        firstScreen ??= frame;
      }
    }
    for (const [target, hotspot] of interactive) {
      const destination = nodes.get(hotspot.target);
      await target.setReactionsAsync([{
        trigger: { type: hotspot.drag ? 'ON_DRAG' : 'ON_CLICK' },
        actions: [{
          type: 'NODE', destinationId: destination.id, navigation: 'NAVIGATE',
          transition: { type: 'DISSOLVE', duration: 0.18, easing: { type: 'EASE_OUT' } },
          preserveScrollPosition: false
        }]
      }]);
    }
    y += Math.ceil(frames.length / columns) * (tallest + gap) + 140;
    count += nodes.size;
  }
  page.flowStartingPoints = starts;
  if (!firstScreen) throw new Error('The starting frame is missing.');
  page.selection = [firstScreen];
  figma.viewport.scrollAndZoomIntoView([firstScreen]);
  figma.closePlugin('BiteMatch imported with ' + count + ' editable frames and two flows.');
}

buildPrototype().catch(error => figma.closePlugin('BiteMatch could not import. ' + error.message));
